				//if(b-1<yy)yy=b-1;					}					if(pathfind[a][b+1]==0)					{						pathfind[a][b+1]=min+1;						c=1;						//if(b+1>yy2)yy2=b+1;					}				}			}		}		for(e=0;e<count_enemys;e++)		{			if(pathfind[ex[e]][ey[e]]!=0)d++;		}		if(d==count_enemys)c=0;		xx--;		yy--;		xx2++;		yy2++;		min++;	}}/*void print_tile(u8 x,u8 y,u16 tilenum,u8 tw,u8 tmw,u8 mask){  u16 a,b,c,d;  //select_image(IMG_TILES);  for(a=0;a<tw;a++)  {    for(b=0;b<tw;b++)    {      d=(tilenum/(tmw/tw));      c=(d*tw)*tmw+(tilenum-d*(tmw/tw))*tw;      //+a+b*tmw      if(mask!=1) draw_tile(x+a,y+b,(tilenum-d*(tmw/tw))*tw+(d*tw)*tmw+a+b*tmw);      else      {        color_key(15);        draw_tile_key(x+a,y+b,(tilenum-d*(tmw/tw))*tw+(d*tw)*tmw+a+b*tmw);      }                  }  }} */void print_tile(u8 x,u8 y,u16 tilenum,u8 tw,u8 tmw,u8 mask){  static u16 c,d,tn;  static u8 a,b,xt;  //select_image(IMG_TILES);  if(tw==1)   {    tn = tilenum;    c = tilenum;  }  else  {    if ( (tw==2) && (tmw == 32))    {        d = (tilenum & 0xfff0) << 2;//        ptile_d = ptile_d << 2;        c = d + ((tilenum & 0x0f) << 1);        tn = c;    }    else    {      d=(tilenum/(tmw/tw));      c=(d*tw)*tmw+(tilenum-d*(tmw/tw))*tw;      tn = c;    }  }  for(a=0;a<tw;a++)  {    xt = x;    for(b=0;b<tw;b++)    {      if(mask!=1)         draw_tile(xt,y,tn);      else      {        color_key(15); draw_tile_key(xt,y,tn);      }      xt++;tn++;    }    y++;    c+=tmw;    tn = c;  }} void redraw_map(u8 templatenum){/*лед - 4дыра - 5камень - 6лава - 17песок - 18труха 19Бочка - 22*/	static u8 a,b,d,x,y,x2,y2,fill,type;	static u16 c;	static u8 *curtempl;	//--------------	/*if(curlevel<3)prespath=0;	if(curlevel>=3&&curlevel<6)prespath=64;	if(curlevel>=6)prespath=128;	*///	clear_screen(0);//	swap_screen();	clear_screen(0);	if(templatenum==254)curtempl=templates[0];	else curtempl=templates[templatenum];	//стены - границы экрана	curmap_tiles[0][0]=7;	curmap_tiles[19][0]=9;	curmap_tiles[0][11]=39;	curmap_tiles[19][11]=41;	for(a=1;a<=18;a++)	{		curmap_tiles[a][0]=8;		curmap_tiles[a][11]=40;		b=rand16()%6;	}	for(a=1;a<=10;a++)	{		curmap_tiles[0][a]=23;		curmap_tiles[19][a]=25;	}	for(a=1;a<19;a+=2)	{		for(b=1;b<11;b+=2)		{			print_tile(a*2,b*2,0+prespath,2,32,0);			print_tile((a+1)*2,b*2,16+prespath,2,32,0);			print_tile(a*2,(b+1)*2,32+prespath,2,32,0);			print_tile((a+1)*2,(b+1)*2,48+prespath,2,32,0);		}	}	for(a=1;a<=7;a+=3)	{		curmap_tiles[a][0]=33;		curmap_tiles[a][1]=49;		curmap_tiles[a][11]=37;		curmap_tiles[a+11][0]=33;		curmap_tiles[a+11][1]=49;		curmap_tiles[a+11][11]=37;	}	curmap_tiles[6][0]=34;	curmap_tiles[13][0]=34;	curmap_tiles[6][11]=38;	curmap_tiles[13][11]=38;		curmap_tiles[0][2]=20;	curmap_tiles[0][9]=20;	curmap_tiles[0][4]=21;	curmap_tiles[0][7]=21;	curmap_tiles[19][2]=35;	curmap_tiles[19][9]=35;	curmap_tiles[19][4]=36;	curmap_tiles[19][7]=36;			color_key(15);	select_image(IMG_TILES);		//забивка наполнения	for(a=1;a<curtempl[0]*6;a+=6)	{		x=curtempl[a];		x2=curtempl[a+1];		y=curtempl[a+2];		y2=curtempl[a+3];		fill=curtempl[a+4];		type=curtempl[a+5];		if(fill==1)		{			for(b=x;b<=x2;b++)			{				for(d=y;d<=y2;d++)				{					curmap_tiles[b][d]=types[type];				}			}		}		if(fill==0)		{			for(b=x;b<=x2;b++)			{				curmap_tiles[b][y]=types[type];				curmap_tiles[b][y2]=types[type];			}			for(d=y;d<=y2;d++)			{				curmap_tiles[x][d]=types[type];				curmap_tiles[x2][d]=types[type];			}		}	}	if(templatenum==254)	{		curmap_tiles[9][5]=26;		curmap_tiles[10][5]=27;		curmap_tiles[9][6]=42;		curmap_tiles[10][6]=43;	}	//№№№№№№№№№№№№№№№№№№№№№№№№№№№№№№	//отрисовка наполнения	for(a=0;a<20;a++)	{		for(b=0;b<12;b++)		{			if(curmap_tiles[a][b]!=0)print_tile(a*2,b*2,curmap_tiles[a][b]+prespath,2,32,1);		}	}		//накладки	if(templatenum!=254)	{		for(a=1;a<19;a++)		{			for(b=1;b<11;b++)			{				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a][b-1]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//верхняя полоска				{					print_tile(a*2,b*2,2+prespath*4,1,32,1);					print_tile(a*2+1,b*2,3+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a][b+1]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//нижняя полоска				{					print_tile(a*2,b*2+1,34+prespath*4,1,32,1);					print_tile(a*2+1,b*2+1,35+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a-1][b]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//левая полоска				{					print_tile(a*2,b*2,4+prespath*4,1,32,1);					print_tile(a*2,b*2+1,36+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a+1][b]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//правая полоска				{					print_tile(a*2+1,b*2,5+prespath*4,1,32,1);					print_tile(a*2+1,b*2+1,37+prespath*4,1,32,1);				}							}		}	}}void draw_map(u8 templatenum,u8 genmon){/*лед - 4дыра - 5камень - 6лава - 17песок - 18труха 19Бочка - 22*/	static u8 a,b,d,x,y,x2,y2,fill,type;	static u16 c;	static u8 *curtempl;	static u8 typesdef[]={4,5,17,6,18,22};	static u8 cnttypes=6;	static liveenemys=1;	//--------------	//a=rand16()%3;	/*if(curlevel<3)prespath=0;	if(curlevel>=3&&curlevel<6)prespath=64;	if(curlevel>=6)prespath=128;	*/	//prespath=a*64;	//if(curlevel<1)prespath=0;	//if(curlevel>=1)prespath=80;	//prespath=64;   	select_image(IMG_TILES); // !!	//clear_screen(0);	// !! swap_screen();	// !! clear_screen(0);	if(templatenum==254)curtempl=templates[0];	else curtempl=templates[templatenum];			if(only_redraw==0)	{		gen_types_enemy(on_level_points);		//gen_types_enemy(300);		for(a=0;a<19;a++)		{			for(b=0;b<11;b++)			{				curmap_tiles[a][b]=0;							}		}		for(a=0;a<32;a++)		{			bullets[a].isfree=1;			bullets[a].sprnum=1;		}		for(b=0;b<2;b++)		{			for(a=1;a<64;a++)			{				spritenums[a]=0;				// !! set_sprite(a,0,0,3);			}			// !! swap_screen();		}			for(a=0;a<16;a++)		{			enemys[a].dead=1;			enemys[a].coin=2;		}	//--------------		types[0]=0;		for(a=1;a<cnttypes;a++)		{			types[a]=typesdef[rand16()%cnttypes];		}	}	//стены - границы экрана	curmap_tiles[0][0]=7;	curmap_tiles[19][0]=9;	curmap_tiles[0][11]=39;	curmap_tiles[19][11]=41;	for(a=1;a<=18;a++)	{		curmap_tiles[a][0]=8;		curmap_tiles[a][11]=40;	}	for(a=1;a<=10;a++)	{		curmap_tiles[0][a]=23;		curmap_tiles[19][a]=25;	}	for(a=1;a<19;a+=2)	{		for(b=1;b<11;b+=2)		{			//c=rand16()%4;			//c*=16;			print_tile(a*2,b*2,0+prespath,2,32,0);			print_tile((a+1)*2,b*2,16+prespath,2,32,0);			print_tile(a*2,(b+1)*2,32+prespath,2,32,0);			print_tile((a+1)*2,(b+1)*2,48+prespath,2,32,0);		}	}	for(a=1;a<=7;a+=3)	{		curmap_tiles[a][0]=33;		curmap_tiles[a][11]=37;		curmap_tiles[a][1]=49;		curmap_tiles[a+11][0]=33;		curmap_tiles[a+11][1]=49;		curmap_tiles[a+11][11]=37;	}	curmap_tiles[6][0]=34;	curmap_tiles[13][0]=34;	curmap_tiles[6][11]=38;	curmap_tiles[13][11]=38;		curmap_tiles[0][2]=20;	curmap_tiles[0][9]=20;	curmap_tiles[0][4]=21;	curmap_tiles[0][7]=21;	curmap_tiles[19][2]=35;	curmap_tiles[19][9]=35;	curmap_tiles[19][4]=36;	curmap_tiles[19][7]=36;	color_key(15);	select_image(IMG_TILES);	//забивка наполнения	for(a=1;a<curtempl[0]*6;a+=6)	{		x=curtempl[a];		x2=curtempl[a+1];		y=curtempl[a+2];		y2=curtempl[a+3];		fill=curtempl[a+4];		type=curtempl[a+5];		if(fill==1)		{			for(b=x;b<=x2;b++)			{				for(d=y;d<=y2;d++)				{					curmap_tiles[b][d]=types[type];				}			}		}		if(fill==0)		{			for(b=x;b<=x2;b++)			{				curmap_tiles[b][y]=types[type];				curmap_tiles[b][y2]=types[type];			}			for(d=y;d<=y2;d++)			{				curmap_tiles[x][d]=types[type];				curmap_tiles[x2][d]=types[type];			}		}	}	if(templatenum==254)	{		curmap_tiles[9][5]=26;		curmap_tiles[10][5]=27;		curmap_tiles[9][6]=42;		curmap_tiles[10][6]=43;	}	if(only_redraw==0)	{		//--- монстры		moncnt=curtempl[(curtempl[0]*6)+1];					//moncnt=curtempl[0];		//if(moncnt>0)moncnt++;		b=0;		for(a=curtempl[0]*6+2;a<curtempl[0]*6+2+moncnt*3;a+=3)		{			monx[b]=curtempl[a];			mony[b]=curtempl[a+1];			montype[b]=curtempl[a+2]-1;			b++;		}		if (genmon==1)		{			if(moncnt>dif_count_mon_in_room[curdif])moncnt=dif_count_mon_in_room[curdif];			if(moncnt>curtempl[(curtempl[0]*6)+1])moncnt=curtempl[(curtempl[0]*6)+1];			count_enemys=moncnt;			//moncnt=4;			for(a=0;a<moncnt;a++)			{				enemys[a].x=monx[a]*8;				enemys[a].y=mony[a]*16;				enemys[a].type=montype[a];				enemys[a].dead=0;				enemys[a].health=types_enemy[montype[a]].health;				enemys[a].picnum=types_enemy[montype[a]].picnum;				enemys[a].sprnum=find_free_sprite();				enemys[a].movdelay=types_enemy[montype[a]].move_delay;				spritenums[enemys[a].sprnum]=1;				enemys[a].animframe=rand16()%4;				enemys[a].animdelay=rand16()%enemyanimdelay;				enemys[a].coin=0;				enemys[a].shoot_delay=rand16()%types_enemy[montype[a]].shoot_delay;			}		}		else		{			count_enemys=0;		}		free_path();		free_path();	}	/*else	{			spritenums[0]=1;		for(a=1;a<64;a++)		{			set_sprite(a,0,0,3);		}		for(a=0;a<32;a++)		{						if(bullets[a].sprnum<64&&bullets[a].isfree==0)spritenums[bullets[a].sprnum]=0;			bullets[a].isfree=1;			//bullets[a].sprnum=63;		}		for(a=0;a<8;a++)		{			//enemys[a].sprnum=find_free_sprite();			for(b=1;b<64;b++)			{				if(spritenums[b]==0&&b<enemys[a].sprnum&&enemys[a].dead==0)				{						if(enemys[a].sprnum<64)spritenums[enemys[a].sprnum]=0;						enemys[a].sprnum=b;						spritenums[b]=1;						break;				}			}		}	}*/		//№№№№№№№№№№№№№№№№№№№№№№№№№№№№№№		//отрисовка наполнения		for(a=0;a<20;a++)		{			for(b=0;b<12;b++)			{								if(curmap_tiles[a][b]!=0)print_tile(a*2,b*2,curmap_tiles[a][b]+prespath,2,32,1);							}		}		//накладки	if(templatenum!=254)	{		for(a=1;a<19;a++)		{			for(b=1;b<11;b++)			{				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a][b-1]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//верхняя полоска				{					print_tile(a*2,b*2,2+prespath*4,1,32,1);					print_tile(a*2+1,b*2,3+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a][b+1]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//нижняя полоска				{					print_tile(a*2,b*2+1,34+prespath*4,1,32,1);					print_tile(a*2+1,b*2+1,35+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a-1][b]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//левая полоска				{					print_tile(a*2,b*2,4+prespath*4,1,32,1);					print_tile(a*2,b*2+1,36+prespath*4,1,32,1);				}				if(curmap_tiles[a][b]!=49&&curmap_tiles[a][b]!=0&&curmap_tiles[a+1][b]!=curmap_tiles[a][b]&&curmap_tiles[a][b]!=6&&curmap_tiles[a][b]!=22)//правая полоска				{					print_tile(a*2+1,b*2,5+prespath*4,1,32,1);					print_tile(a*2+1,b*2+1,37+prespath*4,1,32,1);				}							}		}	}}void gen_global_map(u8 cnt_rooms){	static u8 x,y,a,b,croomx,croomy;	static u8 roomlistx[255];	static u8 roomlisty[255];	static u8 cntrooms;	croomx=croomy=0;	if(lvwalk>=2)	{		lvwalk=0;		prespath+=64;		if(prespath>128)prespath=0;	}	a=prespath/64;	b=rand16()%mus_cnt[a];	lastmus=musnames[a][b];	if(muson==1)music_play(lastmus);	lvwalk++;	for(x=0;x<16;x++)	{		for(y=0;y<16;y++)		{			global_rooms[x][y]=255;			cleared[x][y]=0;		}	}	x=rand16()%16;	y=rand16()%16;	stroomx=x;	stroomy=y;	cntrooms=1;	roomlistx[0]=x;	roomlisty[0]=y;	global_rooms[x][y]=0;	while(cntrooms<cnt_rooms)	{		a=rand16()%cntrooms;		b=rand16()%4;		if(b==0&&roomlisty[a]-1>=0)		{			if(global_rooms[roomlistx[a]][roomlisty[a]-1]==255)			{				//b=rand16()%(count_templates-1);				b=rand16()%(dif_cnt_templates[curdif]-1);				b++;				global_rooms[roomlistx[a]][roomlisty[a]-1]=b;				roomlistx[cntrooms]=roomlistx[a];				roomlisty[cntrooms]=roomlisty[a]-1;				croomx=roomlistx[a];				croomy=roomlisty[a]-1;				cntrooms++;			}			else b++;		}		if(b==1&&roomlisty[a]+1<16)		{			if(global_rooms[roomlistx[a]][roomlisty[a]+1]==255)			{				//b=rand16()%(count_templates-1);				b=rand16()%(dif_cnt_templates[curdif]-1);				b++;				global_rooms[roomlistx[a]][roomlisty[a]+1]=b;				roomlistx[cntrooms]=roomlistx[a];				roomlisty[cntrooms]=roomlisty[a]+1;				croomx=roomlistx[a];				croomy=roomlisty[a]+1;				cntrooms++;			}			else b++;		}				if(b==2&&roomlistx[a]-1>=0)		{			if(global_rooms[roomlistx[a]-1][roomlisty[a]]==255)			{				//b=rand16()%(count_templates-1);				b=rand16()%(dif_cnt_templates[curdif]-1);				b++;				global_rooms[roomlistx[a]-1][roomlisty[a]]=b;				roomlistx[cntrooms]=roomlistx[a]-1;				roomlisty[cntrooms]=roomlisty[a];				croomx=roomlistx[a]-1;				croomy=roomlisty[a];				cntrooms++;			}			else b++;		}		if(b==3&&roomlistx[a]+1<16)		{			if(global_rooms[roomlistx[a]+1][roomlisty[a]]==255)			{				//b=rand16()%(count_templates-1);				b=rand16()%(dif_cnt_templates[curdif]-1);				b++;				global_rooms[roomlistx[a]+1][roomlisty[a]]=b;				roomlistx[cntrooms]=roomlistx[a]+1;				roomlisty[cntrooms]=roomlisty[a];				croomx=roomlistx[a]+1;				croomy=roomlisty[a];				cntrooms++;			}		}	}	global_rooms[croomx][croomy]=254;}void draw_final_boss_map(){	static u8 a,b,d,x,y,x2,y2,fill,type;	static u16 c;	static u8 *curtempl;	static u8 typesdef[]={4,5,17,6,18,22};	static u8 cnttypes=6;	liveenemys=1;	//--------------	pal_select(PAL_FINAL_BOSS);	lastmus=finalbattlemus;	if(muson==1)music_play(finalbattlemus);	for(x=0;x<16;x++)	{		for(y=0;y<16;y++)		{			global_rooms[x][y]=255;			cleared[x][y]=0;		}	}	for(a=0;a<32;a++)	{		bullets[a].isfree=1;		bullets[a].sprnum=1;	}	for(a=0;a<16;a++)	{		enemys[a].dead=1;		enemys[a].coin=0;	}	stroomx=0;	stroomy=0;	global_rooms[stroomx][stroomy]=1;	gen_types_enemy(dif_final_mon_points[curdif]);		for(a=0;a<19;a++)		{			for(b=0;b<11;b++)			{				curmap_tiles[a][b]=0;							}		}		for(b=0;b<2;b++)		{			for(a=1;a<64;a++)			{				spritenums[a]=0;				set_sprite(a,0,0,3);			}			swap_screen();		}		for(a=0;a<32;a++)		{			bullets[a].isfree=1;			bullets[a].sprnum=1;		}		for(a=0;a<16;a++)		{			enemys[a].dead=1;			enemys[a].coin=2;		}	//--------------		types[0]=0;		for(a=1;a<cnttypes;a++)		{			types[a]=typesdef[rand16()%cnttypes];		}	//стены - границы экрана	curmap_tiles[0][0]=7;	curmap_tiles[19][0]=9;	curmap_tiles[0][11]=39;	curmap_tiles[19][11]=41;	for(a=1;a<=18;a++)	{		curmap_tiles[a][0]=8;		curmap_tiles[a][11]=40;	}	for(a=1;a<=10;a++)	{		curmap_tiles[0][a]=23;		curmap_tiles[19][a]=25;	}	color_key(15);	select_image(IMG_TILES);		//забивка наполнения	for(a=8;a<11;a++)	{		for(b=2;b<6;b++)		{			curmap_tiles[a][b]=5;		}	}	for(a=2;a<=5;a++)	{		for(b=1;b<=3;b++)		{			curmap_tiles[a][b]=5;		}	}	for(a=14;a<=17;a++)	{		for(b=1;b<=3;b++)		{			curmap_tiles[a][b]=5;		}	}		for(b=7;b<=9;b++)	{		curmap_tiles[16][b]=5;	}	curmap_tiles[2][6]=5;	curmap_tiles[3][6]=5;	curmap_tiles[2][7]=5;	curmap_tiles[1][7]=5;	curmap_tiles[1][8]=5;	curmap_tiles[17][7]=5;	draw_image(0,0,IMG_FINAL_BOSS);	count_enemys=2;	moncnt=2;	enemys[0].x=32;	enemys[0].y=96;	enemys[0].type=0;	enemys[1].x=128;	enemys[1].y=96;	enemys[1].type=0;	types_enemy[0].picnum=9;	types_enemy[0].numinmas=0;	types_enemy[0].move_type=0;	types_enemy[0].shoot_type=1;	types_enemy[0].shoot_delay=dif_final_brain_delay[curdif];	types_enemy[0].bullifetime=100;	types_enemy[0].power=dif_final_eye_power[curdif];	types_enemy[0].bulspeed=3;	for(a=0;a<8;a++)	{		enemys[a].dead=1;	}	for(a=0;a<2;a++)	{		enemys[a].type=0;		enemys[a].dead=0;		enemys[a].health=dif_final_eye_health[curdif];		enemys[a].picnum=types_enemy[0].picnum;		enemys[a].sprnum=find_free_sprite();		enemys[a].movdelay=types_enemy[0].move_delay;		spritenums[enemys[a].sprnum]=1;		enemys[a].animframe=rand16()%4;		enemys[a].animdelay=rand16()%enemyanimdelay;		enemys[a].coin=0;		enemys[a].shoot_delay=rand16()%types_enemy[0].shoot_delay;	}		free_path();	free_path();	boss_health=dif_final_brain_health[curdif];	boss_cur_shot_type=1;	boss_shoot_delay=dif_final_brain_delay[curdif];	boss_cur_shoot_delay=15;	is_final_battle=1;	}#endif